"""FROZEN additions. Do not edit this file while implementing forge.

These tests cover the gap between a scripted tool harness and a CLI that
finishes a task from one prompt. tests/acceptance/test_forge_cli.py stays
unchanged.
"""

from __future__ import annotations

import json
import textwrap
from pathlib import Path

from test_forge_cli import (
    anthropic_text,
    anthropic_tool,
    assert_ok,
    openai_text,
    openai_tool,
    run_forge,
    serve,
    trace_requests,
    write_script,
)


def write_task(workspace: Path) -> None:
    (workspace / "app.py").write_text(
        "def add(a, b):\n    return a - b\n", encoding="utf-8"
    )
    (workspace / "check.py").write_text(
        "import app\n"
        "if app.add(1, 2) == 3:\n"
        "    print('CHECK_OK')\n"
        "    raise SystemExit(0)\n"
        "print('CHECK_FAIL')\n"
        "raise SystemExit(1)\n",
        encoding="utf-8",
    )


def write_decider(dirpath: Path) -> Path:
    path = dirpath / "decide.py"
    path.write_text(
        textwrap.dedent(
            """\
            import json, sys
            req = json.load(sys.stdin)
            blob = json.dumps(req["messages"])
            if "CHECK_OK" in blob:
                out = {"type": "message", "text": "updated app.py; check passed"}
            elif "return a - b" in blob and "CHECK_FAIL" in blob:
                out = {"type": "tool", "name": "edit_file", "input": {
                    "path": "app.py", "old": "return a - b", "new": "return a + b"}}
            elif "CHECK_FAIL" in blob:
                out = {"type": "tool", "name": "read_file", "input": {"path": "app.py"}}
            else:
                out = {"type": "tool", "name": "bash", "input": {"command": "python check.py"}}
            json.dump(out, sys.stdout)
            """
        ),
        encoding="utf-8",
    )
    return path


def test_autonomous_prompt_fixes_failing_check(tmp_path: Path):
    workspace = tmp_path / "ws"
    workspace.mkdir()
    write_task(workspace)
    decider = write_decider(tmp_path)
    trace = tmp_path / "trace.jsonl"
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--decider",
            str(decider),
            "--permission",
            "bypass",
            "--session-id",
            "auto1",
            "--trace",
            str(trace),
            "-p",
            "Make add(1, 2) return 3. Do not stop until python check.py prints CHECK_OK.",
        ],
    )
    assert_ok(proc)
    assert "updated app.py; check passed" in proc.stdout
    assert (workspace / "app.py").read_text(encoding="utf-8") == "def add(a, b):\n    return a + b\n"
    blob = json.dumps(trace_requests(trace))
    assert "CHECK_FAIL" in blob
    assert "CHECK_OK" in blob
    assert "exit_code=1" in blob
    assert "exit_code=0" in blob
    summary = (workspace / ".forge" / "artifacts" / "auto1" / "summary.txt").read_text(encoding="utf-8")
    assert "app.py" in summary
    assert "check passed" in summary


def protocol_responses(kind: str) -> list:
    tool = openai_tool if kind == "openai" else anthropic_tool
    text = openai_text if kind == "openai" else anthropic_text
    return [
        (tool("glob", {"pattern": "**/*.py"}), 200),
        (tool("read_file", {"path": "app.py"}), 200),
        (tool("bash", {"command": "python check.py"}), 200),
        (tool("edit_file", {"path": "app.py", "old": "return a - b", "new": "return a + b"}), 200),
        (tool("bash", {"command": "python check.py"}), 200),
        (text("task-complete"), 200),
    ]


def run_protocol(tmp_path: Path, kind: str):
    server, handler, port = serve(protocol_responses(kind))
    try:
        workspace = tmp_path / "ws"
        workspace.mkdir()
        write_task(workspace)
        model = "gpt-test" if kind == "openai" else "claude-test"
        key = "sk-test" if kind == "openai" else "sk-ant-test"
        proc = run_forge(
            workspace,
            ["run", "--provider", kind, "--model", model, "--permission", "bypass", "-p", "fix add"],
            env={"FORGE_API_KEY": key, "FORGE_BASE_URL": f"http://127.0.0.1:{port}"},
        )
        assert_ok(proc)
        assert "task-complete" in proc.stdout
        assert (workspace / "app.py").read_text(encoding="utf-8") == "def add(a, b):\n    return a + b\n"
        bodies = [json.dumps(body) for body in handler.bodies]
        assert len(bodies) == 6
        assert "app.py" in bodies[1]
        assert "return a - b" in bodies[2]
        assert "CHECK_FAIL" in bodies[3]
        assert "exit_code=1" in bodies[3]
        assert "CHECK_OK" in bodies[5]
        assert "exit_code=0" in bodies[5]
    finally:
        server.shutdown()


def test_openai_multiturn_protocol(tmp_path: Path):
    run_protocol(tmp_path, "openai")


def test_anthropic_multiturn_protocol(tmp_path: Path):
    run_protocol(tmp_path, "anthropic")


def test_continues_after_ambiguous_edit(tmp_path: Path):
    workspace = tmp_path / "ws"
    workspace.mkdir()
    (workspace / "dup.txt").write_text("keep\na\na\n", encoding="utf-8")
    trace = tmp_path / "trace.jsonl"
    script = write_script(
        tmp_path,
        [
            {"type": "tool", "name": "edit_file", "input": {"path": "dup.txt", "old": "a", "new": "b"}},
            {"type": "tool", "name": "edit_file", "input": {"path": "dup.txt", "old": "keep", "new": "kept"}},
            {"type": "message", "text": "recovered"},
        ],
    )
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(script),
            "--permission",
            "bypass",
            "--trace",
            str(trace),
            "-p",
            "edit carefully",
        ],
    )
    assert_ok(proc)
    assert "recovered" in proc.stdout
    assert (workspace / "dup.txt").read_text(encoding="utf-8") == "kept\na\na\n"
    assert "ambiguous" in json.dumps(trace_requests(trace)).lower()


def test_compaction_keeps_agents_md(tmp_path: Path):
    workspace = tmp_path / "ws"
    workspace.mkdir()
    (workspace / "AGENTS.md").write_text("RULE_ALWAYS_ADD_HEADER\n", encoding="utf-8")
    trace = tmp_path / "trace.jsonl"
    script = write_script(
        tmp_path,
        [
            {"type": "tool", "name": "bash", "input": {"command": "python -c \"print('Q'*300)\""}},
            {"type": "tool", "name": "bash", "input": {"command": "python -c \"print('short-mark')\""}},
            {"type": "message", "text": "compacted"},
        ],
    )
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(script),
            "--permission",
            "bypass",
            "--trace",
            str(trace),
            "-p",
            "read a lot",
        ],
        env={"FORGE_MAX_CONTEXT_CHARS": "500"},
    )
    assert_ok(proc)
    requests = trace_requests(trace)
    last = json.dumps(requests[-1])
    assert "RULE_ALWAYS_ADD_HEADER" in last
    assert "Q" * 80 not in last
    assert "[compacted]" in last
    assert "short-mark" in last


def test_resume_appends_user_message(tmp_path: Path):
    workspace = tmp_path / "ws"
    workspace.mkdir()
    (workspace / "app.py").write_text("v = 1\n", encoding="utf-8")
    first = write_script(tmp_path, [{"type": "message", "text": "partial-answer"}])
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(first),
            "--session-id",
            "steer1",
            "-p",
            "original-task",
        ],
    )
    assert_ok(proc)
    session = (workspace / ".forge" / "sessions" / "steer1.jsonl").read_text(encoding="utf-8")
    assert "original-task" in session
    assert "partial-answer" in session

    missing_dir = tmp_path / "missing-script"
    missing_dir.mkdir()
    missing_script = write_script(missing_dir, [{"type": "message", "text": "unused"}])
    missing = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(missing_script),
            "--session-id",
            "missing",
            "--resume",
            "-p",
            "x",
        ],
    )
    assert missing.returncode == 1

    round2 = tmp_path / "round2"
    round2.mkdir()
    second = write_script(
        round2,
        [
            {"type": "tool", "name": "edit_file", "input": {"path": "app.py", "old": "v = 1", "new": "v = 77"}},
            {"type": "message", "text": "steered"},
        ],
    )
    trace = tmp_path / "resume.jsonl"
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(second),
            "--session-id",
            "steer1",
            "--resume",
            "--permission",
            "bypass",
            "--trace",
            str(trace),
            "-p",
            "use-marker-77",
        ],
    )
    assert_ok(proc)
    assert "steered" in proc.stdout
    assert (workspace / "app.py").read_text(encoding="utf-8") == "v = 77\n"
    first_request = json.dumps(trace_requests(trace)[0])
    assert "original-task" in first_request
    assert "partial-answer" in first_request
    assert "use-marker-77" in first_request


def test_default_permission_does_not_hang(tmp_path: Path):
    workspace = tmp_path / "ws"
    workspace.mkdir()
    trace = tmp_path / "trace.jsonl"
    script = write_script(
        tmp_path,
        [
            {"type": "tool", "name": "bash", "input": {"command": "python -c \"open('ran','w').write('x')\""}},
            {"type": "message", "text": "denied-and-continued"},
        ],
    )
    proc = run_forge(
        workspace,
        [
            "run",
            "--provider",
            "fake",
            "--script",
            str(script),
            "--trace",
            str(trace),
            "-p",
            "run something",
        ],
    )
    assert_ok(proc)
    assert "denied-and-continued" in proc.stdout
    assert not (workspace / "ran").exists()
    assert "permission denied" in json.dumps(trace_requests(trace)).lower()
